import {civicSize} from './civic-footprints.js?v=metropolis-growth-planning-1';
import {REWARDS,rewardSize} from './rewards.js?v=metropolis-growth-planning-1';
import {civicJobSites,civicJobCapacity} from './civic-jobs.js?v=metropolis-growth-planning-1';
import {JobCapacity} from './job-capacity.js?v=metropolis-growth-planning-1';
import {workforceShare} from './workforce.js?v=metropolis-growth-planning-1';
import {routeLength} from './tunnels.js?v=metropolis-growth-planning-1';
import {industrialJobs} from './industry.js?v=metropolis-growth-planning-1';
import {streetGraph,MinQueue} from './highway.js?v=metropolis-growth-planning-1';
import {railNetwork,STATIONS} from './rail.js?v=metropolis-growth-planning-1';
